        when (mesg.getNum()) {
            MesgNum.FILE_ID -> {
                if (fileIdMesgListeners.size == 0) {
                    break
                }

                val fileIdMesg = FileIdMesg(mesg)
                for (mesgListener in fileIdMesgListeners) {
                    mesgListener.onMesg(fileIdMesg)
